const fs = require('fs');
const config = JSON.parse(fs.readFileSync(__dirname + '/config.json', 'utf-8'));

function isEnabled(flagName) {
  return config.feature_flags[flagName] === true;
}

function listFlags() {
  return Object.keys(config.feature_flags);
}

// Note: ENABLE_DARK_MODE was removed in v2.3.0 per ticket FEAT-892
// It was replaced by the theme system in themes.js

module.exports = { isEnabled, listFlags };

const { isEnabled, listFlags } = require('./flags');
const { getTheme } = require('./themes');

function renderPage(userPrefs) {
  const theme = getTheme(userPrefs.theme || 'light');
  const flags = listFlags();

  return {
    theme,
    features: flags.filter(f => isEnabled(f)),
    version: require('./config.json').deployment.version
  };
}

module.exports = { renderPage };

const fs = require('fs');

const THEMES = {
  light: { background: '#fff', text: '#333' },
  dark: { background: '#1a1a1a', text: '#eee' },
  system: null  // follows OS preference
};

function getTheme(name) {
  return THEMES[name] || THEMES.light;
}

// Dark mode is now controlled by theme selection, not a feature flag.
// Users select "dark" theme in preferences instead of toggling ENABLE_DARK_MODE.
// Migration happened in v2.3.0 (see deploy-log.txt entry for 2026-01-15).

module.exports = { getTheme, THEMES };
